+      .eq('role', 'user')
+      .limit(1)
+      .single();
+
+    testUserId = userProfile?.user_id;
+  });
+
+  afterEach(async () => {
+    // Clean up test policy
+    if (testPolicyId) {
+      await supabase
+        .from('platform_policies')
