+      console.log('Skipping: RUN_SUPABASE_E2E not set');
+      return;
+    }
+
+    // Get current TOS
+    const { data: currentTOS } = await supabase.rpc('get_current_policy', {
+      p_policy_type: 'terms_of_service',
