/**
 * Get summary stats for a seller's listings
 * Used by "My Listings" screen header
 * 
 * @param seller_id - Seller user ID
 * @returns Summary statistics
 */
export async function getListingSummary(seller_id: string): Promise<ListingSummary> {
  const { data, error } = await supabase
    .from('items')
    .select('status, price, sold_at')
    .eq('seller_id', seller_id)
    .neq('status', 'deleted');

  if (error) {
    const err = error as Error;
    console.error('[listing] getListingSummary error:', err.message);
    throw new Error(`Failed to fetch listing summary: ${err.message}`);
  }

  const active = data.filter((l) => l.status === 'available').length;
  const sold = data.filter((l) => l.status === 'sold').length;
  const earnings = data
    .filter((l) => l.status === 'sold' && l.sold_at)
    .reduce((sum, l) => sum + l.price, 0);

  return {
    total_active: active,
    total_sold: sold,
    total_earnings_dollars: earnings,
  };
}

export const ALLOWED_MODERATION_STATUSES = ['rejected', 'available', 'needs_edits'] as const;

export type AdminModerationStatus = (typeof ALLOWED_MODERATION_STATUSES)[number];

interface ValidationSuccess {
  ok: true;
  status: AdminModerationStatus;
  reason: string | null;
}

interface ValidationFailure {
  ok: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

interface BuildPayloadInput {
  status: AdminModerationStatus;
  reason: string | null;
  currentAppealCount: number;
}

export function isAdminModerationStatus(value: string): value is AdminModerationStatus {
  return (ALLOWED_MODERATION_STATUSES as readonly string[]).includes(value);
}

export function validateModerationStatusInput(
  rawStatus: string | undefined,
  rawReason: string | undefined
): ValidationResult {
  if (!rawStatus || !isAdminModerationStatus(rawStatus)) {
    return {
      ok: false,
      error: 'status must be one of: rejected, available, needs_edits',
    };
  }

  const reason = rawReason?.trim() || null;
  if ((rawStatus === 'rejected' || rawStatus === 'needs_edits') && !reason) {
    return {
      ok: false,
      error: 'rejection_reason is required when status is rejected or needs_edits',
    };
  }

  return {
    ok: true,
    status: rawStatus,
    reason,
  };
}

export function buildItemStatusUpdatePayload(input: BuildPayloadInput): Record<string, unknown> {
  const nowIso = new Date().toISOString();

  if (input.status === 'rejected') {
    return {
      status: 'rejected',
      rejection_reason: input.reason,
      rejected_at: nowIso,
      appeal_count: input.currentAppealCount + 1,
      edited_since_rejection: false,
      edited_since_rejection_at: null,
    };
  }

  if (input.status === 'needs_edits') {
    return {
      status: 'needs_edits',
      rejection_reason: input.reason,
      rejected_at: null,
      edited_since_rejection: false,
      edited_since_rejection_at: null,
    };
  }

  return {
    status: 'available',
    flagged_at: null,
    rejected_at: null,
    rejection_reason: null,
    appealed_at: null,
    appeal_reason: null,
    edited_since_rejection: false,
    edited_since_rejection_at: null,
  };
}

import { describe, expect, it } from 'vitest';

import {
  buildItemStatusUpdatePayload,
  isAdminModerationStatus,
  validateModerationStatusInput,
} from '../itemModerationStatus';

describe('itemModerationStatus helpers', () => {
  it('accepts supported moderation statuses', () => {
    expect(isAdminModerationStatus('available')).toBe(true);
    expect(isAdminModerationStatus('rejected')).toBe(true);
    expect(isAdminModerationStatus('needs_edits')).toBe(true);
  });

  it('rejects unsupported moderation statuses', () => {
    expect(isAdminModerationStatus('under_review')).toBe(false);
    expect(isAdminModerationStatus('pending_review')).toBe(false);
  });

  it('requires a reason for rejected and needs_edits', () => {
    const rejected = validateModerationStatusInput('rejected', '   ');
    const needsEdits = validateModerationStatusInput('needs_edits', undefined);

    expect(rejected.ok).toBe(false);
    expect(needsEdits.ok).toBe(false);
  });

  it('allows available without a reason', () => {
    const result = validateModerationStatusInput('available', undefined);

    expect(result).toEqual({
      ok: true,
      status: 'available',
      reason: null,
    });
  });

  it('builds rejected payload with timestamp and appeal increment', () => {
    const payload = buildItemStatusUpdatePayload({
      status: 'rejected',
      reason: 'Unsafe product',
      currentAppealCount: 2,
    });

    expect(payload.status).toBe('rejected');
    expect(payload.rejection_reason).toBe('Unsafe product');
    expect(payload.appeal_count).toBe(3);
    expect(payload.edited_since_rejection).toBe(false);
    expect(payload.edited_since_rejection_at).toBeNull();
    expect(typeof payload.rejected_at).toBe('string');
  });

  it('builds needs_edits payload with moderation note and no rejected_at', () => {
    const payload = buildItemStatusUpdatePayload({
      status: 'needs_edits',
      reason: 'Please replace blurry image and clarify age range',
      currentAppealCount: 1,
    });

    expect(payload).toEqual({
      status: 'needs_edits',
      rejection_reason: 'Please replace blurry image and clarify age range',
      rejected_at: null,
      edited_since_rejection: false,
      edited_since_rejection_at: null,
    });
  });

  it('builds available payload that clears moderation fields', () => {
    const payload = buildItemStatusUpdatePayload({
      status: 'available',
      reason: null,
      currentAppealCount: 7,
    });

    expect(payload).toEqual({
      status: 'available',
      flagged_at: null,
      rejected_at: null,
      rejection_reason: null,
      appealed_at: null,
      appeal_reason: null,
      edited_since_rejection: false,
      edited_since_rejection_at: null,
    });
  });
});

