import { useState, useEffect } from 'react';
import type { AdminConfigItem, SMSRateLimitStats } from '@/types/config';

export default function ConfigPage() {
  const [config, setConfig] = useState<AdminConfigItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editValues, setEditValues] = useState<Record<string, string>>({});
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [canWrite, setCanWrite] = useState<boolean | null>(null);

  const adminSecret = process.env.NEXT_PUBLIC_ADMIN_UI_SECRET || '';

  const loadConfigFromApi = async () => {
    setLoading(true);
    setError(null);
    try {
      // Cache-bust to avoid any browser/CDN caching of the API response
      const res = await fetch(`/api/admin/config?ts=${Date.now()}`, { cache: 'no-store' });
      const json = await res.json();
      if (json.error) throw new Error(json.error);

      // Filter out any invalid items (missing key or value)
      const validConfig = (json.data || []).filter((item: any) => item && item.key && item.value !== undefined);

      // Ensure critical moderation settings are always present in UI
      // (RPC upsert will create them on save if missing).
      const moderationFallbacks: AdminConfigItem[] = [
        {
          key: 'moderation_ai_enabled',
          value: 'true',
          data_type: 'boolean',
          category: 'moderation',
          description: 'Enable or disable Google Vision AI image moderation on listing photo upload.',
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
        {
          key: 'moderation_appeal_max_attempts',
          value: '3',
          data_type: 'number',
          category: 'moderation',
          description: 'Maximum number of appeal attempts a seller can submit for a rejected listing.',
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
        {
          key: 'moderation_appeal_window_days',
          value: '14',
          data_type: 'number',
          category: 'moderation',
          description: 'Number of days after rejection during which a seller may submit an appeal.',
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
      ];

      moderationFallbacks.forEach((fallback) => {
        if (!validConfig.some((item: AdminConfigItem) => item.key === fallback.key)) {
          validConfig.push(fallback);
        }
      });

      setConfig(validConfig);
      // read can_write flag from server
      setCanWrite(!!json.can_write);
      const initial: Record<string, string> = {};
      validConfig.forEach((item: AdminConfigItem) => (initial[item.key] = String(item.value ?? '')));
      setEditValues(initial);
    } catch (err: any) {
      setError(err.message || 'Failed to load configuration');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadConfigFromApi();
  }, []);

  const handleSave = async (key: string) => {
    setSaving(true);
    setError(null);
    setSuccess(null);
    try {
      console.log(`[Config Save] Attempting to save ${key} with value:`, editValues[key]);

      const res = await fetch('/api/admin/config', {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'x-admin-secret': adminSecret,
        },
        body: JSON.stringify({ key, value: editValues[key] }),
      });

      console.log(`[Config Save] Response status:`, res.status);
      const json = await res.json();
      console.log(`[Config Save] Response body:`, json);

      if (!res.ok || json.error) {
        throw new Error(json.error || `HTTP ${res.status}`);
      }

      setSuccess(`Successfully updated ${key}`);
      console.log(`[Config Save] ✅ Success! Updated: ${key} = ${editValues[key]}`);

      // Reload config from API
      await loadConfigFromApi();
      setTimeout(() => setSuccess(null), 5000);
    } catch (err: any) {
      const errorMsg = err.message || 'Failed to save configuration';
      console.error(`[Config Save] ❌ Error:`, errorMsg, err);
      setError(errorMsg);
    } finally {
      setSaving(false);
    }
  };



  const getConfigDescription = (key: string): string => {
    const descriptions: Record<string, string> = {
      sms_rate_limit_per_hour: 'Maximum number of SMS verification codes that can be sent per hour per phone number. Helps prevent SMS spam and abuse.',
      verification_code_expiry_minutes: 'How long verification codes remain valid before expiring (in minutes).',
