+        add('TC-RPC-004', false, current.error?.message || 'No policy for publish test');
+      } else {
+        const adminTry = await admin.rpc('publish_policy', {
+          p_policy_id: current.data.id,
+          p_admin_id: created.adminUserId,
+        });
+        const userTry = await admin.rpc('publish_policy', {
+          p_policy_id: current.data.id,
+          p_admin_id: created.regularUserId,
+        });
+        const okAdmin = !adminTry.error;
+        const okUserDenied = !!userTry.error;
+        add('TC-RPC-004', okAdmin && okUserDenied, `admin=${okAdmin ? 'ok' : adminTry.error?.message}; nonAdmin=${okUserDenied ? 'denied' : 'unexpected-ok'}`);
+      }
+    }
+
+    // RLS tests
+    {
+      const published = await admin
+        .from('platform_policies')
+        .insert({
+          policy_type: 'privacy_policy',
+          version: `1.0.${String(ts).slice(-3)}`,
+          title: 'Temp Published Policy',
+          content: 'published',
+          status: 'published',
+          effective_date: new Date().toISOString(),
+          created_by: created.adminUserId,
+          published_by: created.adminUserId,
+          published_at: new Date().toISOString(),
+        })
+        .select('id')
+        .single();
+      if (published.data?.id) created.policyIds.push(published.data.id);
+
+      const anonRead = await anon.from('platform_policies').select('id').eq('status', 'published').limit(5);
+      add('TC-RLS-001', !anonRead.error && Array.isArray(anonRead.data), anonRead.error ? anonRead.error.message : `rows=${anonRead.data.length}`);
+    }
+
+    {
+      const draft = await admin
+        .from('platform_policies')
+        .insert({
+          policy_type: 'liability_disclaimer',
+          version: `1.0.${String(ts).slice(-2)}`,
+          title: 'Temp Draft Policy',
+          content: 'draft',
+          status: 'draft',
+          effective_date: new Date().toISOString(),
+          created_by: created.adminUserId,
+        })
+        .select('id')
+        .single();
+      if (draft.data?.id) created.policyIds.push(draft.data.id);
+
+      const anonDraft = await anon.from('platform_policies').select('id').eq('status', 'draft').limit(5);
+      add('TC-RLS-002', !anonDraft.error && Array.isArray(anonDraft.data) && anonDraft.data.length === 0, anonDraft.error ? anonDraft.error.message : `draftRowsVisible=${anonDraft.data.length}`);
+    }
+
+    {
+      const userClient = createClient(url, anonKey, { auth: { autoRefreshToken: false, persistSession: false } });
+      const signIn = await userClient.auth.signInWithPassword({ email: regularEmail, password: regularPassword });
+
+      if (signIn.error || !signIn.data?.user?.id) {
+        add('TC-RLS-003', false, signIn.error?.message || 'Regular user sign-in failed');
+      } else {
+        const policy = await admin
+          .from('platform_policies')
+          .select('id,version')
+          .eq('status', 'published')
+          .limit(1)
+          .maybeSingle();
+
+        if (!policy.data?.id) {
+          add('TC-RLS-003', false, 'No published policy for acceptance visibility check');
+        } else {
+          const ins = await admin.from('policy_acceptances').insert({
+            user_id: signIn.data.user.id,
+            policy_id: policy.data.id,
+            policy_type: 'terms_of_service',
+            policy_version: policy.data.version || '1.0',
+            accepted_at: new Date().toISOString(),
+          });
+          if (ins.error && !ins.error.message.toLowerCase().includes('duplicate')) {
+            add('TC-RLS-003', false, `seed insert failed: ${ins.error.message}`);
+          } else {
+            const own = await userClient.from('policy_acceptances').select('*').eq('user_id', signIn.data.user.id);
+            const other = await userClient.from('policy_acceptances').select('*').neq('user_id', signIn.data.user.id);
+            const ok = !own.error && !other.error && Array.isArray(own.data) && Array.isArray(other.data) && other.data.length === 0;
+            add('TC-RLS-003', ok, ok ? `ownRows=${own.data.length}; otherRows=0` : `ownErr=${own.error?.message || 'none'}; otherErr=${other.error?.message || 'none'}; otherRows=${other.data?.length ?? 'n/a'}`);
+          }
+        }
+      }
+    }
+
+    console.log(JSON.stringify(result, null, 2));
+  } catch (e) {
+    add('RUNNER', false, e instanceof Error ? e.message : String(e));
+    console.log(JSON.stringify(result, null, 2));
+    process.exitCode = 1;
+  } finally {
+    await cleanup();
+  }
+})();
